input.command:
@(
  'LANGFUSE_PUBLIC_KEY',
  'LANGFUSE_SECRET_KEY',
  'LANGFUSE_HOST',
  'LANGFUSE_BASE_URL',
  'LANGFUSE_AUTH'
) | ForEach-Object {
  $v = [Environment]::GetEnvironmentVariable($_, 'Process')
  if (-not $v) { $v = [Environment]::GetEnvironmentVariable($_, 'User') }
  if (-not $v) { $v = [Environment]::GetEnvironmentVariable($_, 'Machine') }
  if ($v) { "$_=SET (len=$($v.Length))" } else { "$_=NOT SET" }
}
Write-Host '---'
if (Test-Path .env) { Write-Host '.env: EXISTS'; Select-String -Path .env -Pattern 'LANGFUSE|langfuse' -SimpleMatch:$false } else { Write-Host '.env: MISSING' }
if (Test-Path .env.local) { Write-Host '.env.local: EXISTS' } else { Write-Host '.env.local: MISSING' }
Write-Host '---'
Get-ChildItem -Force -File | Where-Object { $_.Name -match 'env|langfuse|secret|credential' } | Select-Object Name
Write-Host '---'
Get-Content .cursor\settings.json -ErrorAction SilentlyContinue

Write-Host 'Process/User/Machine presence (values hidden):'
foreach ($name in @('LANGFUSE_PUBLIC_KEY','LANGFUSE_SECRET_KEY','LANGFUSE_HOST','LANGFUSE_BASE_URL','LANGFUSE_AUTH','LANGFUSE_PK','LANGFUSE_SK')) {
  $p = [Environment]::GetEnvironmentVariable($name, 'Process')
  $u = [Environment]::GetEnvironmentVariable($name, 'User')
  $m = [Environment]::GetEnvironmentVariable($name, 'Machine')
  $scopes = @()
  if ($p) { $scopes += 'Process' }
  if ($u) { $scopes += 'User' }
  if ($m) { $scopes += 'Machine' }
  if ($scopes.Count -gt 0) { Write-Host "$name : LOADED ($($scopes -join ', '))" } else { Write-Host "$name : NOT LOADED" }
}
Write-Host ''
Write-Host 'Project env files:'
@('.env','.env.local','.env.development','.env.production') | ForEach-Object {
  if (Test-Path $_) { Write-Host "$_ : EXISTS" } else { Write-Host "$_ : missing" }
}
Write-Host ''
Write-Host 'Code references (project files only):'
Get-ChildItem -File -Include *.py,*.json,*.md,*.yml,*.yaml,*.toml,*.js,*.ts,*.env* -Recurse -ErrorAction SilentlyContinue |
  Where-Object { $_.FullName -notmatch '\\venv\\|\\\.git\\' } |
  Select-String -Pattern 'langfuse|LANGFUSE' -SimpleMatch:$false |
  Select-Object -First 30 Path, LineNumber, Line

Write-Host 'Process/User/Machine presence (values hidden):'
foreach ($name in @('LANGFUSE_PUBLIC_KEY','LANGFUSE_SECRET_KEY','LANGFUSE_HOST','LANGFUSE_BASE_URL','LANGFUSE_AUTH','LANGFUSE_PK','LANGFUSE_SK')) {
  $p = [Environment]::GetEnvironmentVariable($name, 'Process')
  $u = [Environment]::GetEnvironmentVariable($name, 'User')
  $m = [Environment]::GetEnvironmentVariable($name, 'Machine')
  $scopes = @()
  if ($p) { $scopes += 'Process' }
  if ($u) { $scopes += 'User' }
  if ($m) { $scopes += 'Machine' }
  if ($scopes.Count -gt 0) { Write-Host "$name : LOADED ($($scopes -join ', '))" } else { Write-Host "$name : NOT LOADED" }
}
Write-Host ''
Write-Host 'Project env files:'
@('.env','.env.local','.env.development','.env.production') | ForEach-Object {
  if (Test-Path $_) {
    $has = Select-String -Path $_ -Pattern '^LANGFUSE_' -SimpleMatch:$false -ErrorAction SilentlyContinue
    if ($has) {
      Write-Host "$_ : EXISTS (LANGFUSE_* keys present: $($has.Count))"
      $has | ForEach-Object { $k = ($_ -split '=',2)[0].Trim(); Write-Host "  - $k" }
    } else {
      Write-Host "$_ : EXISTS (no LANGFUSE_* keys)"
    }
  } else {
    Write-Host "$_ : missing"
  }
}
Write-Host ''
Write-Host 'Cursor langfuse settings:'
if (Test-Path .cursor\settings.json) { Get-Content .cursor\settings.json }
